insert into public.campaigns (business_id,title,summary,pitch,use_of_funds,type,sector,location,risk,goal,min_investment,deadline,equity_percent,valuation,interest_rate,tenor_months,rewards,status,approved_at) values
((select id from ids where email='business@demo.com'),'Cold storage expansion for mango season','Add a 200-tonne cold room to cut post-harvest losses by 30%.','We supply 14 supermarket outlets in Dhaka and lose almost a third of our produce in peak season because we lack cold storage near the farms. A 200-tonne cold room in Rajshahi lets us hold stock, sell at better prices and sign two more retail contracts already in negotiation.','Cold room construction 60%, refrigerated van 25%, working capital 15%.','equity','Agriculture','Rajshahi','medium',2500000,25000,current_date+28,10,25000000,null,null,'[]','live',now()),
((select id from ids where email='solar@demo.com'),'Solar for 50 garment factories','Finance rooftop solar installs repaid from factories'' electricity savings.','Factories pay us monthly from what they save on grid electricity. We have letters of intent from 50 factories in Gazipur and Savar and need inventory finance to install panels before the dry season.','Panels and inverters 80%, installation crews 15%, insurance 5%.','debt','Renewable Energy','Dhaka','low',5000000,10000,current_date+45,null,null,12,24,'[]','live',now()),
((select id from ids where email='textile@demo.com'),'Revive 30 handloom weavers','Back artisan weavers and get handmade jamdani as a thank-you.','Each pledge funds yarn and looms for weavers in our cooperative. Backers receive handmade products shipped anywhere in Bangladesh.','Looms 50%, yarn 30%, weaver training 20%.','reward','Textiles & Garments','Chattogram','low',600000,1500,current_date+20,null,null,null,null,'[{"amount":1500,"title":"Thank-you card + scarf","description":"Handwoven cotton scarf."},{"amount":5000,"title":"Jamdani dupatta","description":"Signed by the weaver."},{"amount":15000,"title":"Full jamdani saree","description":"Custom colour, 8-week delivery."}]','live',now()),
((select id from ids where email='business@demo.com'),'Working capital for winter vegetables','Short-term loan to pre-purchase seeds and inputs for 120 contract farmers.','Repaid from supermarket receivables within 9 months.','Seeds and fertiliser 70%, farmer advances 30%.','debt','Agriculture','Rajshahi','medium',1200000,20000,current_date+35,null,null,14,9,'[]','pending',null);
