insert into public.questions (campaign_id, investor_id, body) select c.id, i.id, v.body from (values
('Cold storage expansion for mango season','investor@demo.com','Who will hold the shares, and will investors get board observer rights?'),
('Solar for 50 garment factories','karim@demo.com','What happens if a factory stops paying?')) v(title,email,body) join public.campaigns c on c.title=v.title join ids i on i.email=v.email;
