-- Demo data for the LOCAL preview only (npm run local:db). Never run against a real project.
-- Expects the demo auth users created by scripts/local-supabase.sh.
create temp table ids as select email, id from auth.users;
update public.user_roles set role='admin' where user_id=(select id from ids where email='admin@demo.com');
delete from public.investor_prefs where user_id=(select id from ids where email='admin@demo.com');
select set_config('request.jwt.claim.sub', (select id::text from ids where email='admin@demo.com'), false);
update public.investor_prefs set sectors='{Agriculture,"Renewable Energy"}', types='{equity,debt}', min_ticket=10000, max_ticket=500000, risk='medium' where user_id=(select id from ids where email='investor@demo.com');
update public.investor_prefs set locations='{Dhaka}', max_ticket=100000, risk='low' where user_id=(select id from ids where email='karim@demo.com');
select c.id, i.id, v.amount from (values ('Cold storage expansion for mango season','investor@demo.com',200000),('Solar for 50 garment factories','karim@demo.com',50000),('Solar for 50 garment factories','investor@demo.com',150000),('Revive 30 handloom weavers','karim@demo.com',5000),('Cold storage expansion for mango season','karim@demo.com',600000)) v(title,email,amount)
join public.campaigns c on c.title=v.title join ids i on i.email=v.email;
update public.questions set answer='Shares are issued directly to investors. Anyone investing ৳5 lakh or more gets quarterly reports and an observer seat at the AGM.', answered_at=now() where body like 'Who will hold%';
